#pragma once

#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include <nlohmann/json.hpp>
#include <string>
#include <vector>
#include <optional>
#include <algorithm>

namespace ptv {

// Dependency (save_persistence) tag protocol — copied from ledger exports for loose coupling
// Inputs we may publish:
//   "save.request:", "load.request:", "mission.complete:", "recharge.complete:",
//   "save.register:", "save.section.push:"
// Outputs we may listen to (not used here):
//   "save.collect.start:", "save.completed:", "load.section:", "load.completed:"
static constexpr const char* TAG_SAVE_REQUEST_PREFIX = "save.request:";
static constexpr const char* TAG_SAVE_SECTION_PUSH_PREFIX = "save.section.push:";

// HUD & Wrist Menu interop prefixes defined by this mechanic
static constexpr const char* TAG_UI_TOAST_PREFIX = "ui.toast:";                  // {"text":"...","ttl_s":2.0}
static constexpr const char* TAG_UI_MENU_OPEN_PREFIX = "ui.menu.open:";          // {"pages":[{id,title}],"opacity":0..1}
static constexpr const char* TAG_UI_MENU_CLOSE_PREFIX = "ui.menu.close:";        // {}
static constexpr const char* TAG_UI_PAGE_REGISTER_PREFIX = "ui.page.register:";  // {"id":"locomotion","title":"Locomotion","order":10}
static constexpr const char* TAG_UI_HUD_ENABLE_PREFIX = "hud.enable:";           // {"on":true}
static constexpr const char* TAG_UI_HUD_MODE_PREFIX = "hud.mode:";               // {"mode":"full|minimal|targets"}
static constexpr const char* TAG_UI_HUD_STYLE_PREFIX = "hud.style:";             // {"high_contrast":bool,"opacity":0..1}

// Inputs expected on our own CMechanicBinding entry (driven by test harness)
//  { x_tap:bool, x_hold:bool, x_pressed:bool, health01:float, ring_energy:float, will_focus:float }

struct WristPageDef {
    std::string id;
    std::string title;
    int order{100};
};

struct HudStateData {
    float health01{1.0f};
    float ring_energy{100.0f};
    float will_focus{0.0f};
};

// Helper to push a tag string onto an entity's CTag vector (create if missing)
inline void push_tag(World& w, std::uint32_t e, const std::string& tag) {
    if (!w.valid(e)) return;
    if (w.has<CTag>(e)) {
        auto& v = w.get<CTag>(e).tags;
        v.emplace_back(tag);
    } else {
        CTag t; t.tags.emplace_back(tag);
        w.emplace_or_replace<CTag>(e, std::move(t));
    }
}

inline std::optional<nlohmann::json> parse_tag_json(const std::string& s, const char* prefix) {
    if (s.rfind(prefix, 0) != 0) return std::nullopt;
    auto j = nlohmann::json::parse(s.c_str() + std::char_traits<char>::length(prefix), nullptr, false);
    if (!j.is_discarded()) return j;
    return std::nullopt;
}

// Forward declaration of the mechanic class
class HudAndWristMenu : public IMechanic {
public:
    void on_attach(World& world, std::uint32_t entity, const nlohmann::json& params) override;
    void on_update(World& world, std::uint32_t entity, float dt) override;
    void on_detach(World& world, std::uint32_t entity) override;
    std::string id() const override { return "generated.hud_and_wrist_menu"; }

private:
    // Internal helpers
    void handle_binding_inputs(World& world, std::uint32_t entity, const nlohmann::json& j);
    void scan_and_register_pages(World& world);
    void publish_menu_open(World& world, std::uint32_t entity);
    void publish_menu_close(World& world, std::uint32_t entity);
    void persist_settings_now(World& world, std::uint32_t entity);
    void publish_hud_mode(World& world, std::uint32_t entity);
    void publish_hud_style(World& world, std::uint32_t entity);

private:
    // Session state
    bool hud_on_{true};
    int hud_mode_index_{0}; // 0=full,1=minimal,2=targets
    bool menu_open_{false};
    float ui_opacity_{0.9f};
    bool high_contrast_{false};
    float t_since_attach_{0.0f};
    bool toast_prompt_sent_{false};

    // Registry of external pages
    std::vector<WristPageDef> pages_{}; // kept sorted by order then title

    // Cached HUD data (purely for annunciators if a visual layer listens)
    HudStateData hud_data_{};
};

} // namespace ptv

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include <nlohmann/json.hpp>
#include <string>
#include "hud_wrist_shared.h"

namespace ptv {

void HudAndWristMenu::on_attach(World& world, std::uint32_t entity, const nlohmann::json& params) {
    // Read optional defaults
    ui_opacity_ = std::clamp(params.value("ui_opacity", ui_opacity_), 0.2f, 1.0f);
    high_contrast_ = params.value("high_contrast", high_contrast_);

    // Enable HUD immediately
    push_tag(world, entity, std::string(TAG_UI_HUD_ENABLE_PREFIX) + nlohmann::json({{"on", true}}).dump());
    publish_hud_style(world, entity);
    publish_hud_mode(world, entity);

    // Intro toast to guide player ("on spawn" behavior). Shown once per attach.
    const float ttl = 4.0f;
    const char* tip = "Open Wrist Menu (X) to choose locomotion and comfort.";
    push_tag(world, entity, std::string(TAG_UI_TOAST_PREFIX) + nlohmann::json({{"text", tip}, {"ttl_s", ttl}}).dump());
    toast_prompt_sent_ = true;

    // Pre-scan for externally registered pages already present in scene
    scan_and_register_pages(world);
}

void HudAndWristMenu::on_detach(World& world, std::uint32_t entity) {
    // Close any open menu and persist settings defensively
    if (menu_open_) {
        publish_menu_close(world, entity);
        persist_settings_now(world, entity);
    }
}

} // namespace ptv

PTV_REGISTER_MECHANIC("generated.hud_and_wrist_menu", ptv::HudAndWristMenu)

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include <nlohmann/json.hpp>
#include <entt/entt.hpp>
#include <string>
#include <vector>
#include <algorithm>
#include "hud_wrist_shared.h"

namespace ptv {

static std::string mode_name_from_index(int i) {
    switch (i % 3) {
        case 0: return "full";
        case 1: return "minimal";
        default: return "targets";
    }
}

void HudAndWristMenu::publish_hud_mode(World& world, std::uint32_t entity) {
    push_tag(world, entity, std::string(TAG_UI_HUD_MODE_PREFIX) + nlohmann::json({{"mode", mode_name_from_index(hud_mode_index_)}}).dump());
}

void HudAndWristMenu::publish_hud_style(World& world, std::uint32_t entity) {
    push_tag(world, entity, std::string(TAG_UI_HUD_STYLE_PREFIX) + nlohmann::json({{"high_contrast", high_contrast_}, {"opacity", ui_opacity_}}).dump());
}

void HudAndWristMenu::publish_menu_open(World& world, std::uint32_t entity) {
    // Ensure pages are up-to-date before opening
    scan_and_register_pages(world);
    // Build pages array
    nlohmann::json arr = nlohmann::json::array();
    for (auto& p : pages_) arr.push_back({{"id", p.id}, {"title", p.title}});
    nlohmann::json j = {{"pages", arr}, {"opacity", ui_opacity_}};
    push_tag(world, entity, std::string(TAG_UI_MENU_OPEN_PREFIX) + j.dump());
}

void HudAndWristMenu::publish_menu_close(World& world, std::uint32_t entity) {
    push_tag(world, entity, std::string(TAG_UI_MENU_CLOSE_PREFIX) + nlohmann::json::object().dump());
}

void HudAndWristMenu::persist_settings_now(World& world, std::uint32_t entity) {
    // Compose a single settings blob under our section key
    nlohmann::json data = {
        {"hud_on", hud_on_},
        {"hud_mode", mode_name_from_index(hud_mode_index_)},
        {"high_contrast", high_contrast_},
        {"ui_opacity", ui_opacity_}
    };
    nlohmann::json push = {{"section", "settings.hud"}, {"data", data}};
    push_tag(world, entity, std::string(TAG_SAVE_SECTION_PUSH_PREFIX) + push.dump());
    // Request an immediate save flush (manager may debounce internally)
    nlohmann::json req = {{"immediate", true}};
    push_tag(world, entity, std::string(TAG_SAVE_REQUEST_PREFIX) + req.dump());
}

void HudAndWristMenu::scan_and_register_pages(World& world) {
    auto& reg = world.registry();
    auto view = reg.view<CTag>();
    for (auto e : view) {
        auto& tags = view.get<CTag>(e).tags;
        for (auto& s : tags) {
            auto jOpt = parse_tag_json(s, TAG_UI_PAGE_REGISTER_PREFIX);
            if (!jOpt) continue;
            const auto& j = *jOpt;
            if (!j.is_object()) continue;
            WristPageDef def;
            def.id = j.value("id", "");
            def.title = j.value("title", def.id);
            def.order = j.value("order", 100);
            if (def.id.empty()) continue;
            auto it = std::find_if(pages_.begin(), pages_.end(), [&](const WristPageDef& p){return p.id == def.id;});
            if (it == pages_.end()) {
                pages_.push_back(def);
            } else {
                // Update title/order if re-registered
                it->title = def.title;
                it->order = def.order;
            }
        }
    }
    std::sort(pages_.begin(), pages_.end(), [](const WristPageDef& a, const WristPageDef& b){
        if (a.order != b.order) return a.order < b.order;
        return a.title < b.title;
    });
}

void HudAndWristMenu::handle_binding_inputs(World& world, std::uint32_t entity, const nlohmann::json& j) {
    // Resource meters (optional inputs)
    hud_data_.health01 = std::clamp(j.value("health01", hud_data_.health01), 0.0f, 1.0f);
    hud_data_.ring_energy = std::max(0.0f, j.value("ring_energy", hud_data_.ring_energy));
    hud_data_.will_focus = std::clamp(j.value("will_focus", hud_data_.will_focus), 0.0f, 1000.0f);

    const bool x_tap = j.value("x_tap", false);
    const bool x_hold = j.value("x_hold", false);
    const bool x_pressed = j.value("x_pressed", false);

    // Open/close menu on press/hold; cycle HUD mode on tap if menu closed
    if ((x_hold || x_pressed) && !menu_open_) {
        menu_open_ = true;
        publish_menu_open(world, entity);
        return;
    }
    if ((x_hold || x_pressed) && menu_open_) {
        // Toggle off on re-press
        menu_open_ = false;
        publish_menu_close(world, entity);
        persist_settings_now(world, entity);
        return;
    }
    if (x_tap && !menu_open_) {
        hud_mode_index_ = (hud_mode_index_ + 1) % 3;
        publish_hud_mode(world, entity);
    }

    // Optional direct style tweaks from input
    if (j.contains("toggle_high_contrast") && j.at("toggle_high_contrast").get<bool>()) {
        high_contrast_ = !high_contrast_;
        publish_hud_style(world, entity);
    }
    if (j.contains("opacity_delta")) {
        float d = j.at("opacity_delta").get<float>();
        ui_opacity_ = std::clamp(ui_opacity_ + d, 0.2f, 1.0f);
        publish_hud_style(world, entity);
    }
}

void HudAndWristMenu::on_update(World& world, std::uint32_t entity, float dt) {
    t_since_attach_ += dt;

    // Pull inputs from our own binding entry (params_json)
    if (world.has<CMechanicBinding>(entity)) {
        const auto& mb = world.get<CMechanicBinding>(entity);
        for (const auto& entry : mb.entries) {
            // Match either exact id or builtin route (id field is authoritative here)
            if (entry.id == id() || entry.builtin_id == id()) {
                auto j = nlohmann::json::parse(entry.params_json, nullptr, false);
                if (j.is_object()) {
                    handle_binding_inputs(world, entity, j);
                }
            }
        }
    }

    // Keep HUD enable tag alive if it was toggled externally
    if (hud_on_) {
        push_tag(world, entity, std::string(TAG_UI_HUD_ENABLE_PREFIX) + nlohmann::json({{"on", true}}).dump());
    }
}

} // namespace ptv

